    /// Calculate the bounds of a geometry after projection.
    ///
    /// Returns `((min_x, min_y), (max_x, max_y))`
    pub fn bounds(&self, geometry: &GeoJsonGeometry) -> ((f64, f64), (f64, f64)) {
        let coords = self.geometry_coordinates(geometry);
        if coords.is_empty() {
            return ((f64::NAN, f64::NAN), (f64::NAN, f64::NAN));
        }

        let mut min_x = f64::MAX;
        let mut max_x = f64::MIN;
        let mut min_y = f64::MAX;
        let mut max_y = f64::MIN;

        for &(lon, lat) in coords.iter() {
            let (x, y) = self.projection.project(lon, lat);
            if x < min_x {
                min_x = x;
            }
            if x > max_x {
                max_x = x;
            }
            if y < min_y {
                min_y = y;
            }
            if y > max_y {
                max_y = y;
            }
        }

        ((min_x, min_y), (max_x, max_y))
    }

    /// Calculate the centroid of a geometry after projection.
    pub fn centroid(&self, geometry: &GeoJsonGeometry) -> (f64, f64) {
        let coords = self.geometry_coordinates(geometry);
        if coords.is_empty() {
            return (f64::NAN, f64::NAN);
        }

        let mut sum_x = 0.0;
        let mut sum_y = 0.0;
        let n = coords.len() as f64;

        for &(lon, lat) in coords.iter() {
            let (x, y) = self.projection.project(lon, lat);
            sum_x += x;
            sum_y += y;
        }

        (sum_x / n, sum_y / n)
    }

    /// Extract all coordinates from a geometry.
    pub(super) fn geometry_coordinates<'a>(
        &self,
        geometry: &'a GeoJsonGeometry,
    ) -> Cow<'a, [(f64, f64)]> {
        match geometry {
            GeoJsonGeometry::Point(lon, lat) => Cow::Owned(vec![(*lon, *lat)]),
            GeoJsonGeometry::MultiPoint(points) => Cow::Borrowed(points),
            GeoJsonGeometry::LineString(coords) => Cow::Borrowed(coords),
            GeoJsonGeometry::MultiLineString(lines) => {
                Cow::Owned(lines.iter().flatten().copied().collect())
            }
            GeoJsonGeometry::Polygon(rings) => {
                Cow::Owned(rings.iter().flatten().copied().collect())
            }
            GeoJsonGeometry::MultiPolygon(polygons) => {
                Cow::Owned(polygons.iter().flatten().flatten().copied().collect())
            }
        }
    }
